customComponents.FaqSection:
"use client";

import { useState } from "react";
import { Plus, Minus } from 'lucide-react';

export default function FaqSection({ data }: any) {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  const toggle = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <section className="bg-background py-20 lg:py-28">
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        <div className="grid grid-cols-1 gap-12 lg:grid-cols-12 lg:gap-16">
          {/* Left column: heading */}
          <div className="lg:col-span-4">
            <div className="lg:sticky lg:top-28">
              {data?.sectionTitle && (
                <h2
                  className="text-3xl font-semibold tracking-tight text-foreground sm:text-4xl"
                  style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                >
                  {data.sectionTitle}
                </h2>
              )}
              {data?.sectionDescription && (
                <p
                  className="mt-5 text-base leading-relaxed text-foreground/70"
                  style={{ fontFamily: "'Inter', sans-serif" }}
                >
                  {data.sectionDescription}
                </p>
              )}
              <div className="mt-8 hidden h-px w-16 bg-primary lg:block" aria-hidden="true" />
            </div>
          </div>

          {/* Right column: FAQ list */}
          <div className="lg:col-span-8">
            <div className="border border-gray-200 rounded-none divide-y divide-gray-200 bg-background">
              {Array.isArray(data?.faqs) &&
                data.faqs.map((faq: any, index: number) => {
                  const isOpen = openIndex === index;
                  return (
                    <div key={index} className="group">
                      <button
                        type="button"
                        onClick={() => toggle(index)}
                        aria-expanded={isOpen}
                        className="flex w-full items-start justify-between gap-6 px-6 py-6 text-left transition-colors duration-200 hover:bg-gray-50 sm:px-8"
                      >
                        <span className="flex items-baseline gap-4">
                          <span
                            className="text-sm tabular-nums text-foreground/40"
                            style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                          >
                            {String(index + 1).padStart(2, "0")}
                          </span>
                          <span
                            className={`text-base font-medium sm:text-lg transition-colors duration-200 ${
                              isOpen ? "text-primary" : "text-foreground group-hover:text-primary"
                            }`}
                            style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                          >
                            {typeof faq?.question === "string" ? faq.question : ""}
                          </span>
                        </span>
                        <span
                          className={`mt-1 flex h-7 w-7 flex-none items-center justify-center border transition-all duration-300 ${
                            isOpen
                              ? "border-primary bg-primary text-background"
                              : "border-gray-200 text-foreground/60 group-hover:border-primary group-hover:text-primary"
                          }`}
                          aria-hidden="true"
                        >
                          {isOpen ? (
                            <Minus className="h-3.5 w-3.5" strokeWidth={2} />
                          ) : (
                            <Plus className="h-3.5 w-3.5" strokeWidth={2} />
                          )}
                        </span>
                      </button>
                      <div
                        className={`grid transition-all duration-300 ease-in-out ${
                          isOpen ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
                        }`}
                      >
                        <div className="overflow-hidden">
                          <p
                            className="px-6 pb-7 pl-[4.25rem] pr-8 text-base leading-relaxed text-foreground/70 sm:px-8 sm:pl-[4.75rem]"
                            style={{ fontFamily: "'Inter', sans-serif" }}
                          >
                            {typeof faq?.answer === "string" ? faq.answer : ""}
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                })}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

customComponents.HeroSection:
import Link from 'next/link'
import Image from 'next/image'
import { CheckCircle, ArrowRight, Star } from 'lucide-react'

export default function HeroSection({ data }: any) {
  const bgSrc =
    typeof data?.backgroundImage === 'string'
      ? data.backgroundImage
      : data?.backgroundImage?.src
  const bgAlt =
    typeof data?.backgroundImage === 'object' && data?.backgroundImage?.alt
      ? data.backgroundImage.alt
      : 'Hero background'

  const statImgSrc =
    typeof data?.floatingStat?.image === 'string'
      ? data.floatingStat.image
      : data?.floatingStat?.image?.src

  return (
    <section className="relative bg-background overflow-hidden">
      <div className="mx-auto max-w-7xl border-x border-gray-200">
        <div className="grid grid-cols-1 lg:grid-cols-2">
          {/* Left: Text Content */}
          <div className="flex flex-col justify-center px-6 py-16 sm:px-10 lg:px-14 lg:py-24">
            {data?.eyebrow && (
              <div className="mb-6 flex items-center gap-3">
                <span className="h-px w-8 bg-primary" />
                <span className="text-xs font-semibold uppercase tracking-[0.2em] text-primary">
                  {data.eyebrow}
                </span>
              </div>
            )}

            {data?.headline && (
              <h1 className="font-heading text-4xl font-bold leading-[1.05] tracking-tight text-foreground sm:text-5xl lg:text-6xl">
                {data.headline}
              </h1>
            )}

            {data?.subheadline && (
              <p className="mt-6 max-w-xl text-base leading-relaxed text-foreground/70 sm:text-lg">
                {data.subheadline}
              </p>
            )}

            {/* CTAs */}
            <div className="mt-10 flex flex-col gap-3 sm:flex-row sm:items-center">
              {data?.primaryCtaText && data?.primaryCtaLink && (
                <Link
                  href={data.primaryCtaLink}
                  className="group inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-7 py-4 text-sm font-semibold text-white transition-all duration-300 hover:opacity-90"
                >
                  {data.primaryCtaText}
                  <ArrowRight className="h-4 w-4 transition-transform duration-300 group-hover:translate-x-1" />
                </Link>
              )}
              {data?.secondaryCtaText && data?.secondaryCtaLink && (
                <Link
                  href={data.secondaryCtaLink}
                  className="inline-flex items-center justify-center rounded-xl border border-gray-200 bg-background px-7 py-4 text-sm font-semibold text-foreground transition-colors duration-300 hover:border-primary hover:text-primary"
                >
                  {data.secondaryCtaText}
                </Link>
              )}
            </div>

            {/* Review Snippet */}
            {data?.reviewSnippet && (
              <div className="mt-10 flex items-center gap-4 border-t border-gray-200 pt-8">
                {Array.isArray(data.reviewSnippet.avatars) &&
                  data.reviewSnippet.avatars.length > 0 && (
                    <div className="flex -space-x-3">
                      {data.reviewSnippet.avatars.map(
                        (avatar: any, i: number) => {
                          const avatarSrc =
                            typeof avatar === 'string' ? avatar : avatar?.src
                          if (!avatarSrc) return null
                          return (
                            <div
                              key={i}
                              className="relative h-10 w-10 overflow-hidden rounded-full border-2 border-background"
                            >
                              <Image
                                src={avatarSrc}
                                alt="Reviewer avatar"
                                fill
                                className="object-cover"
                              />
                            </div>
                          )
                        }
                      )}
                    </div>
                  )}
                <div>
                  <div className="flex items-center gap-1.5">
                    <div className="flex items-center gap-0.5">
                      {[...Array(5)].map((_, i) => (
                        <Star
                          key={i}
                          className="h-4 w-4 fill-primary text-primary"
                        />
                      ))}
                    </div>
                    <span className="text-sm font-bold text-foreground">
                      {data.reviewSnippet.rating}
                    </span>
                  </div>
                  {data.reviewSnippet.text && (
                    <p className="mt-0.5 text-sm text-foreground/60">
                      {data.reviewSnippet.text}
                    </p>
                  )}
                </div>
              </div>
            )}

            {/* Trust Marks */}
            {Array.isArray(data?.trustMarks) && data.trustMarks.length > 0 && (
              <div className="mt-8 flex flex-wrap items-center gap-x-6 gap-y-3">
                {data.trustMarks.map((mark: any, i: number) => (
                  <div key={i} className="flex items-center gap-2">
                    <CheckCircle className="h-4 w-4 flex-shrink-0 text-primary" />
                    <span className="text-sm font-medium text-foreground/80">
                      {typeof mark === 'string' ? mark : JSON.stringify(mark)}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Right: Image */}
          <div className="relative min-h-[400px] border-t border-gray-200 lg:min-h-0 lg:border-l lg:border-t-0">
            {bgSrc && (
              <div className="relative h-full w-full">
                <div className="absolute inset-0 p-4 sm:p-6">
                  <div className="relative h-full w-full overflow-hidden rounded-xl">
                    <Image
                      src={bgSrc}
                      alt={bgAlt}
                      fill
                      priority
                      className="object-cover transition-transform duration-700 hover:scale-105"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-surface-dark/40 via-transparent to-transparent" />
                  </div>
                </div>
              </div>
            )}

            {/* Floating Stat Card */}
            {data?.floatingStat && (
              <div className="absolute bottom-10 left-6 right-6 sm:left-auto sm:right-12 sm:w-auto">
                <div className="flex items-center gap-4 rounded-xl border border-white/20 bg-surface-dark/70 p-5 backdrop-blur-md">
                  {statImgSrc && (
                    <div className="relative h-14 w-14 flex-shrink-0 overflow-hidden rounded-xl">
                      <Image
                        src={statImgSrc}
                        alt={data.floatingStat.label || 'Stat'}
                        fill
                        className="object-cover"
                      />
                    </div>
                  )}
                  <div>
                    <p className="font-heading text-3xl font-bold text-surface-dark-foreground">
                      {data.floatingStat.value}
                    </p>
                    <p className="mt-0.5 text-sm text-surface-dark-foreground/70">
                      {data.floatingStat.label}
                    </p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}

customComponents.AboutSection:
import Image from 'next/image'
