              {data.callToAction?.text && data.callToAction?.href && (
                <div className="mt-10">
                  <Link
                    href={data.callToAction.href}
                    className="group inline-flex items-center gap-3 rounded-xl bg-primary px-6 py-3.5 text-sm font-medium text-white transition-colors duration-300 hover:bg-primary/90"
                    style={{ fontFamily: 'Inter, sans-serif' }}
                  >
                    {data.callToAction.text}
                    <ArrowRight className="h-4 w-4 transition-transform duration-300 group-hover:translate-x-1" />
                  </Link>
