              {imageSrc && (
                <div className="relative w-full overflow-hidden rounded-xl border border-gray-200">
                  <div className="relative aspect-[16/10] w-full">
                    <Image
                      src={imageSrc}
                      alt={imageAlt}
                      fill
                      className="object-cover transition-transform duration-700 ease-out hover:scale-[1.03]"
                      sizes="(min-width: 1024px) 55vw, 100vw"
                    />
                  </div>
                </div>
              )}

              {data.content && (
                <div
                  className={`${
                    imageSrc ? 'mt-10 border-t border-gray-200 pt-10' : ''
                  }`}
                >
                  <p
                    className="text-base lg:text-lg leading-8 text-foreground/80 whitespace-pre-line"
                    style={{ fontFamily: 'Inter, sans-serif' }}
                  >
                    {typeof data.content === 'string'
                      ? data.content
                      : JSON.stringify(data.content)}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Bottom divider */}
        <div className="mt-16 lg:mt-20 border-t border-gray-200" />
      </div>
    </section>
  )
}

customComponents.WhyUsSection:
import * as LucideIcons from 'lucide-react';
import { CheckCircle2 } from 'lucide-react';

function ItemIcon({ name }: { name?: string }) {
  if (name && typeof name === 'string') {
    const icons: any = LucideIcons;
    const pascal = name
      .split(/[-_\s]+/)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join('');
    const IconComponent = icons[pascal] || icons[name];
    if (IconComponent && typeof IconComponent === 'function') {
      return <IconComponent className="h-6 w-6" strokeWidth={1.5} />;
    }
  }
  return <CheckCircle2 className="h-6 w-6" strokeWidth={1.5} />;
}

export default function WhyUsSection({ data }: any) {
  if (!data) return null;

  const items = Array.isArray(data.items) ? data.items : [];

  return (
    <section className="bg-background py-20 sm:py-28">
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {/* Section Header */}
        <div className="max-w-3xl">
          {data.sectionTitle && (
            <h2
              className="text-3xl font-semibold tracking-tight text-foreground sm:text-4xl lg:text-5xl"
              style={{ fontFamily: "'Space Grotesk', sans-serif" }}
            >
              {data.sectionTitle}
            </h2>
          )}
          {data.sectionDescription && (
            <p
              className="mt-5 text-base leading-relaxed text-foreground/70 sm:text-lg"
              style={{ fontFamily: "'Inter', sans-serif" }}
            >
              {data.sectionDescription}
            </p>
          )}
        </div>

        {/* Divider */}
        <div className="mt-12 border-t border-gray-200" />

        {/* Grid of USPs */}
        {items.length > 0 && (
          <div className="mt-12 grid grid-cols-1 border-l border-t border-gray-200 sm:grid-cols-2 lg:grid-cols-3">
            {items.map((item: any, index: number) => (
              <div
                key={index}
                className="group relative flex flex-col border-b border-r border-gray-200 bg-background p-8 transition-colors duration-300 hover:bg-primary/5 lg:p-10"
              >
                {/* Index marker */}
                <div className="flex items-start justify-between">
                  <div className="flex h-12 w-12 items-center justify-center rounded-none border border-gray-200 text-primary transition-colors duration-300 group-hover:border-primary group-hover:bg-primary group-hover:text-background">
                    <ItemIcon name={item?.icon} />
                  </div>
                  <span
                    className="text-sm tabular-nums text-foreground/30 transition-colors duration-300 group-hover:text-primary"
                    style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                  >
                    {String(index + 1).padStart(2, '0')}
                  </span>
                </div>

                {item?.title && (
                  <h3
                    className="mt-8 text-lg font-medium tracking-tight text-foreground sm:text-xl"
                    style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                  >
                    {item.title}
                  </h3>
                )}

                {item?.description && (
                  <p
                    className="mt-3 text-sm leading-relaxed text-foreground/70 sm:text-base"
                    style={{ fontFamily: "'Inter', sans-serif" }}
                  >
                    {item.description}
                  </p>
                )}

                {/* Precision accent line */}
                <div className="mt-auto pt-8">
                  <div className="h-px w-8 bg-gray-200 transition-all duration-500 group-hover:w-16 group-hover:bg-primary" />
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

customComponents.BrandsSection:
import Image from 'next/image';

export default function BrandsSection({ data }: any) {
  const brands = Array.isArray(data?.brands) ? data.brands : [];

  if (brands.length === 0) return null;

  return (
    <section className="bg-background py-16 sm:py-20">
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {data?.sectionTitle && (
          <div className="mb-10 flex items-center gap-6">
            <h2
              className="shrink-0 text-sm font-semibold uppercase tracking-[0.2em] text-foreground/70"
              style={{ fontFamily: "'Space Grotesk', sans-serif" }}
            >
              {data.sectionTitle}
            </h2>
            <div className="h-px w-full border-t border-gray-200" aria-hidden="true" />
          </div>
        )}

        <div className="grid grid-cols-2 border border-gray-200 sm:grid-cols-3 lg:grid-cols-6">
          {brands.map((brand: any, index: number) => {
            const logoSrc =
              typeof brand?.logo === 'string' ? brand.logo : brand?.logo?.src;
            const logoAlt =
              typeof brand?.logo === 'object' && brand?.logo?.alt
                ? brand.logo.alt
                : brand?.name;

            return (
              <div
                key={index}
                className="group flex flex-col items-center justify-center gap-3 border border-gray-200 bg-background px-6 py-10 transition-colors duration-300 hover:bg-primary/5"
              >
                {logoSrc && (
                  <div className="relative h-12 w-full max-w-[120px]">
                    <Image
                      src={logoSrc}
                      alt={logoAlt || ''}
                      fill
                      className="object-contain grayscale opacity-60 transition-all duration-300 group-hover:grayscale-0 group-hover:opacity-100"
                      sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 16vw"
                    />
                  </div>
                )}
                {brand?.name && (
                  <span
                    className="text-xs font-medium uppercase tracking-widest text-foreground/50 transition-colors duration-300 group-hover:text-foreground"
                    style={{ fontFamily: "'Inter', sans-serif" }}
                  >
                    {brand.name}
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

customComponents.FindUsSection:
import Link from 'next/link';
import { Clock, Phone, Mail, MapPin, ArrowUpRight } from 'lucide-react';

export default function FindUsSection({ data }: any) {
  if (!data) return null;

  const directionsHref = data?.address
    ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(data.address)}`
    : '#';

  return (
    <section className="bg-background py-20 md:py-28">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="mb-12 max-w-3xl border-b border-gray-200 pb-10">
          {data?.sectionTitle && (
            <h2
              className="text-3xl font-bold tracking-tight text-foreground sm:text-4xl md:text-5xl"
              style={{ fontFamily: "'Space Grotesk', sans-serif" }}
            >
              {data.sectionTitle}
            </h2>
          )}
          {data?.sectionDescription && (
            <p
              className="mt-4 text-base leading-relaxed text-foreground/70 md:text-lg"
              style={{ fontFamily: "'Inter', sans-serif" }}
            >
              {data.sectionDescription}
            </p>
          )}
        </div>

        {/* 2-Column Layout */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-5">
          {/* Left: Map with floating address card */}
          <div className="relative overflow-hidden rounded-xl border border-gray-200 lg:col-span-3">
            <div className="relative h-[420px] w-full md:h-[520px] lg:h-full lg:min-h-[560px]">
              {data?.mapUrl && (
                <iframe
                  src={data.mapUrl}
                  className="absolute inset-0 h-full w-full"
                  style={{ border: 0 }}
                  allowFullScreen
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                  title="Location map"
