                        </Link>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Right: Two stacked bento cards */}
          <div className="flex flex-col gap-6 lg:col-span-2">
            {/* Opening Hours Card */}
            {data?.hours && (
