customComponents.GallerySection:
"use client";

import { useState, useCallback, useEffect } from "react";
import Image from "next/image";
import { X, ChevronLeft, ChevronRight, Plus } from 'lucide-react';

type GalleryImage = {
  image: string | { src?: string; alt?: string };
  caption?: string;
};

function getSrc(img: GalleryImage["image"]): string {
  return typeof img === "string" ? img : img?.src || "";
}

function getAlt(item: GalleryImage, fallback: string): string {
  if (typeof item.image === "object" && item.image?.alt) return item.image.alt;
  if (item.caption) return item.caption;
  return fallback;
}

export default function GallerySection({ data }: any) {
  const images: GalleryImage[] = Array.isArray(data?.images) ? data.images : [];
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const close = useCallback(() => setActiveIndex(null), []);
  const prev = useCallback(() => {
    setActiveIndex((i) => (i === null ? null : (i - 1 + images.length) % images.length));
  }, [images.length]);
  const next = useCallback(() => {
    setActiveIndex((i) => (i === null ? null : (i + 1) % images.length));
  }, [images.length]);

  useEffect(() => {
    if (activeIndex === null) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") close();
      if (e.key === "ArrowLeft") prev();
      if (e.key === "ArrowRight") next();
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [activeIndex, close, prev, next]);

  useEffect(() => {
    if (activeIndex !== null) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [activeIndex]);

  if (!images.length && !data?.sectionTitle) return null;

  return (
    <section className="bg-background text-foreground py-20 md:py-28">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="border-b border-gray-200 pb-10 md:pb-12">
          <div className="grid grid-cols-1 md:grid-cols-12 gap-6 md:gap-10 items-end">
            <div className="md:col-span-7">
              {data?.sectionTitle && (
                <h2 className="font-[Space_Grotesk,sans-serif] text-3xl md:text-4xl lg:text-5xl font-semibold tracking-tight text-foreground">
                  {data.sectionTitle}
                </h2>
              )}
            </div>
            <div className="md:col-span-5">
              {data?.sectionDescription && (
                <p className="text-base md:text-lg leading-relaxed text-foreground/70">
                  {data.sectionDescription}
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Grid */}
        {images.length > 0 && (
          <div className="mt-10 md:mt-14 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-px border border-gray-200 bg-gray-200 rounded-none">
            {images.map((item, index) => {
              const src = getSrc(item.image);
              if (!src) return null;
              return (
                <button
                  key={index}
                  type="button"
                  onClick={() => setActiveIndex(index)}
                  className="group relative bg-background p-4 md:p-5 text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-primary transition-colors"
                  aria-label={item.caption || `Open image ${index + 1}`}
                >
                  <div className="relative aspect-[4/3] w-full overflow-hidden rounded-xl">
                    <Image
                      src={src}
