customComponents.BeforeAfterSection:
"use client";

import { useState, useRef, useCallback } from "react";
import Image from "next/image";
import { MoveHorizontal } from 'lucide-react';

function getImageSrc(img: any): string {
  if (!img) return "";
  return typeof img === "string" ? img : img?.src || "";
}

function getImageAlt(img: any, fallback: string): string {
  if (img && typeof img === "object" && img.alt) return img.alt;
  return fallback;
}

function ComparisonSlider({ item, index }: { item: any; index: number }) {
  const [position, setPosition] = useState(50);
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const updatePosition = useCallback((clientX: number) => {
    const container = containerRef.current;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    const x = clientX - rect.left;
    const pct = Math.min(100, Math.max(0, (x / rect.width) * 100));
    setPosition(pct);
  }, []);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      setIsDragging(true);
      (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
      updatePosition(e.clientX);
    },
    [updatePosition]
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging) return;
      updatePosition(e.clientX);
    },
    [isDragging, updatePosition]
  );

  const handlePointerUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  const beforeSrc = getImageSrc(item?.beforeImage);
  const afterSrc = getImageSrc(item?.afterImage);

  return (
    <article className="group border border-gray-200 bg-background rounded-none flex flex-col">
      <div
        ref={containerRef}
        className="relative aspect-[4/3] w-full overflow-hidden rounded-xl m-3 mb-0 cursor-ew-resize select-none touch-none"
        style={{ width: "calc(100% - 1.5rem)" }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
      >
        {afterSrc && (
          <Image
            src={afterSrc}
            alt={getImageAlt(item?.afterImage, item?.title ? `${item.title} — after` : "After")}
            fill
            className="object-cover"
            sizes="(min-width: 1024px) 50vw, 100vw"
            draggable={false}
          />
        )}

        {beforeSrc && (
          <div
            className="absolute inset-0 overflow-hidden"
            style={{ clipPath: `inset(0 ${100 - position}% 0 0)` }}
          >
            <Image
              src={beforeSrc}
              alt={getImageAlt(item?.beforeImage, item?.title ? `${item.title} — before` : "Before")}
              fill
              className="object-cover"
              sizes="(min-width: 1024px) 50vw, 100vw"
              draggable={false}
            />
          </div>
        )}

        {/* Divider line + handle */}
        <div
          className="absolute top-0 bottom-0 w-px bg-white/90 pointer-events-none"
          style={{ left: `${position}%` }}
        >
          <div
            className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center w-10 h-10 rounded-full bg-background border border-gray-200 text-primary transition-transform duration-200 ${
              isDragging ? "scale-110" : "group-hover:scale-105"
            }`}
          >
            <MoveHorizontal className="w-4 h-4" />
          </div>
        </div>

        {/* Labels */}
        <span className="absolute top-3 left-3 text-[11px] font-medium uppercase tracking-widest px-2.5 py-1 bg-surface-dark/70 text-surface-dark-foreground backdrop-blur-sm pointer-events-none">
          Before
        </span>
        <span className="absolute top-3 right-3 text-[11px] font-medium uppercase tracking-widest px-2.5 py-1 bg-primary text-background pointer-events-none">
          After
        </span>
      </div>

      {(item?.title || item?.description) && (
        <div className="p-6 pt-5 flex flex-col gap-2">
          <div className="flex items-baseline gap-4">
            <span
              className="text-xs font-medium text-primary tabular-nums"
              style={{ fontFamily: "Space Grotesk, sans-serif" }}
            >
              {String(index + 1).padStart(2, "0")}
            </span>
            {item?.title && (
              <h3
                className="text-lg font-semibold text-foreground tracking-tight"
                style={{ fontFamily: "Space Grotesk, sans-serif" }}
              >
                {item.title}
              </h3>
            )}
          </div>
          {item?.description && (
            <p
              className="text-sm leading-relaxed text-foreground/60"
              style={{ fontFamily: "Inter, sans-serif" }}
            >
              {item.description}
            </p>
          )}
        </div>
      )}
    </article>
  );
}

