customComponents.TestimonialsSection:
import { Star, Quote } from 'lucide-react';

export default function TestimonialsSection({ data }: any) {
  const renderStars = (rating: number) => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      const filled = rating >= i;
      const partial = !filled && rating > i - 1;
      stars.push(
        <span key={i} className="relative inline-block">
          <Star className="w-4 h-4 text-foreground/20" strokeWidth={1.5} />
          {(filled || partial) && (
            <span
              className="absolute inset-0 overflow-hidden"
              style={{ width: filled ? '100%' : `${(rating - (i - 1)) * 100}%` }}
            >
              <Star className="w-4 h-4 text-accent fill-accent" strokeWidth={1.5} />
            </span>
          )}
        </span>
      );
    }
    return stars;
  };

  return (
    <section className="bg-background py-20 sm:py-28">
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {/* Section Header */}
        <div className="max-w-3xl border-b border-gray-200 pb-12">
          {data?.sectionTitle && (
            <h2
              className="text-3xl sm:text-4xl lg:text-5xl font-semibold tracking-tight text-foreground"
              style={{ fontFamily: "'Space Grotesk', sans-serif" }}
            >
              {data.sectionTitle}
            </h2>
          )}
          {data?.sectionDescription && (
            <p
              className="mt-5 text-base sm:text-lg leading-relaxed text-foreground/60"
              style={{ fontFamily: "'Inter', sans-serif" }}
            >
              {data.sectionDescription}
            </p>
          )}
        </div>

        {/* Testimonials Grid */}
        {Array.isArray(data?.testimonials) && data.testimonials.length > 0 && (
          <div className="mt-0 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 border-l border-gray-200">
            {data.testimonials.map((testimonial: any, index: number) => (
              <article
                key={index}
                className="group relative flex flex-col border-r border-b border-gray-200 bg-background p-8 lg:p-10 rounded-none transition-colors duration-300 hover:bg-primary/[0.03]"
              >
                {/* Quote icon */}
                <div className="mb-6 flex items-center justify-between">
                  <Quote
                    className="w-8 h-8 text-primary/20 transition-colors duration-300 group-hover:text-primary/40"
                    strokeWidth={1.25}
                  />
                  {typeof testimonial?.rating === 'number' && (
                    <div className="flex items-center gap-2">
                      <div className="flex items-center gap-0.5">
                        {renderStars(testimonial.rating)}
                      </div>
                      <span
                        className="text-xs font-medium tabular-nums text-foreground/50"
                        style={{ fontFamily: "'Inter', sans-serif" }}
                      >
                        {testimonial.rating.toFixed(1)}
                      </span>
                    </div>
                  )}
                </div>

                {/* Quote text */}
                {testimonial?.quote && (
                  <blockquote
                    className="flex-1 text-base sm:text-lg leading-relaxed text-foreground/80 [&_strong]:font-semibold [&_strong]:text-primary"
                    style={{ fontFamily: "'Inter', sans-serif" }}
                    dangerouslySetInnerHTML={{ __html: testimonial.quote }}
                  />
                )}

                {/* Attribution */}
                <footer className="mt-8 flex items-center gap-4 border-t border-gray-200 pt-6">
                  <div
                    className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-primary text-sm font-semibold text-white"
                    style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                    aria-hidden="true"
                  >
                    {typeof testimonial?.name === 'string'
                      ? testimonial.name
                          .split(' ')
                          .map((part: string) => part.charAt(0))
                          .slice(0, 2)
                          .join('')
                          .toUpperCase()
                      : ''}
                  </div>
                  <div className="min-w-0">
                    {testimonial?.name && (
                      <p
                        className="truncate text-sm font-semibold text-foreground"
                        style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                      >
                        {testimonial.name}
                      </p>
                    )}
                    {testimonial?.location && (
                      <p
                        className="truncate text-sm text-foreground/50"
                        style={{ fontFamily: "'Inter', sans-serif" }}
                      >
                        {testimonial.location}
                      </p>
                    )}
                  </div>
                </footer>
              </article>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

