                        style={{ fontFamily: "'Inter', sans-serif" }}
                      >
                        {typeof feature === 'string'
                          ? feature
                          : JSON.stringify(feature)}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}
